#define MAX_N 100
#define MAX_QUEUE 10000

typedef struct {
    int x, y;
    int dist;
} Point;

int main() {
    int n, m, k;
    scanf("%d %d %d", &n, &m, &k);

    // Read start position (1-indexed)
    int start_x, start_y;
    scanf("%d %d", &start_x, &start_y);

    // Create grid (1-indexed for simplicity)
    bool grid[MAX_N + 2][MAX_N + 2] = {false};
    bool visited[MAX_N + 2][MAX_N + 2] = {false};

    // Mark obstacles
    for (int i = 0; i < m; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        grid[x][y] = true;  // obstacle
    }

    // BFS queue
    Point queue[MAX_QUEUE];
    int front = 0, rear = 0;

    // Start BFS from start position
    queue[rear].x = start_x;
    queue[rear].y = start_y;
    queue[rear].dist = 0;
    rear++;
    visited[start_x][start_y] = true;

    // Directions for hexagonal grid (even-r offset coordinates)
    // For a hex grid where odd rows are shifted right:
    int dx[] = {-1, -1, 0, 0, 1, 1};
    int dy_odd[] = {0, 1, -1, 1, 0, 1};   // for odd x (row)
    int dy_even[] = {-1, 0, -1, 1, -1, 0}; // for even x (row)

    int reachable = 0;

    while (front < rear) {
        Point current = queue[front];
        front++;

        if (current.dist <= k) {
            reachable++;
        }

        if (current.dist == k) continue;

        // Try all 6 directions
        for (int dir = 0; dir < 6; dir++) {
            int nx = current.x + dx[dir];
            int ny;

            // Determine y offset based on row parity
            if (current.x % 2 == 1) {  // odd row
                ny = current.y + dy_odd[dir];
            } else {  // even row
                ny = current.y + dy_even[dir];
            }

            // Check bounds
            if (nx < 1 || nx > n || ny < 1 || ny > n) continue;

            // Check if obstacle or visited
            if (grid[nx][ny] || visited[nx][ny]) continue;

            visited[nx][ny] = true;
            queue[rear].x = nx;
            queue[rear].y = ny;
            queue[rear].dist = current.dist + 1;
            rear++;
        }
    }

    printf("%d\n", reachable);

    return 0;
}

