/*
   Hexagonal grid reachability with obstacles.

   Assumed input format:
   t n
   x1 y1
   x2 y2
   ...
   xn yn

   Start position is (0, 0).
   In one turn, you may move to one of 6 adjacent hex cells.
   Count how many cells are reachable from (0,0) in at most t turns,
   excluding obstacle cells and not passing through obstacles.

   Hex coordinates used: axial (x, y)
   Neighbors:
     (x+1, y), (x-1, y), (x, y+1), (x, y-1), (x+1, y-1), (x-1, y+1)

   Since only cells within distance <= t matter, we restrict BFS to that region.
*/

typedef long long ll;

typedef struct {
    int x, y;
} Node;

static inline ll key_xy(int x, int y) {
    return (((ll)x) << 32) ^ (unsigned int)y;
}

int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int has_key(ll *arr, int n, ll k) {
    int l = 0, r = n - 1;
    while (l <= r) {
        int m = (l + r) >> 1;
        if (arr[m] == k) return 1;
        if (arr[m] < k) l = m + 1;
        else r = m - 1;
    }
    return 0;
}

static inline int hex_dist(int x, int y) {
    int z = -x - y;
    int ax = x < 0 ? -x : x;
    int ay = y < 0 ? -y : y;
    int az = z < 0 ? -z : z;
    int mx = ax > ay ? ax : ay;
    return mx > az ? mx : az;
}

int main(void) {
    int t, n;
    if (scanf("%d %d", &t, &n) != 2) return 0;

    ll *obs = NULL;
    if (n > 0) {
        obs = (ll *)malloc((size_t)n * sizeof(ll));
        for (int i = 0; i < n; i++) {
            int x, y;
            scanf("%d %d", &x, &y);
            obs[i] = key_xy(x, y);
        }
        qsort(obs, n, sizeof(ll), cmp_ll);
        int m = 0;
        for (int i = 0; i < n; i++) {
            if (i == 0 || obs[i] != obs[i - 1]) obs[m++] = obs[i];
        }
        n = m;
    }

    if (has_key(obs, n, key_xy(0, 0))) {
        printf("0\n");
        free(obs);
        return 0;
    }

    int side = 2 * t + 1;
    int total = side * side;

    char *vis = (char *)calloc((size_t)total, sizeof(char));
    Node *q = (Node *)malloc((size_t)total * sizeof(Node));

    int dirs[6][2] = {
        { 1,  0},
        {-1,  0},
        { 0,  1},
        { 0, -1},
        { 1, -1},
        {-1,  1}
    };

    int head = 0, tail = 0;
    int ox = t, oy = t;

    q[tail++] = (Node){0, 0};
    vis[ox * side + oy] = 1;
    int answer = 1;

    while (head < tail) {
        Node cur = q[head++];
        int cd = hex_dist(cur.x, cur.y);
        if (cd == t) continue;

        for (int k = 0; k < 6; k++) {
            int nx = cur.x + dirs[k][0];
            int ny = cur.y + dirs[k][1];

            if (hex_dist(nx, ny) > t) continue;
            if (has_key(obs, n, key_xy(nx, ny))) continue;

            int ix = nx + t;
            int iy = ny + t;
            int id = ix * side + iy;
            if (!vis[id]) {
                vis[id] = 1;
                q[tail++] = (Node){nx, ny};
                answer++;
            }
        }
    }

    printf("%d\n", answer);

    free(obs);
    free(vis);
    free(q);
    return 0;
}

