import java.io.*;
import java.util.*;

/*
 * Hexagonal grid reachability with obstacles.
 *
 * We are given:
 * - number of turns n
 * - number of obstacles m
 * - m obstacle coordinates
 *
 * Start position is (0, 0).
 * In one turn, we may move to one of 6 neighboring hex cells.
 * We must count how many cells are reachable from (0,0) in at most n turns,
 * without stepping on obstacles.
 *
 * Coordinate system used:
 * neighbors of (x, y) are
 * (x+1, y), (x-1, y), (x, y+1), (x, y-1), (x+1, y-1), (x-1, y+1)
 *
 * This is a standard axial-coordinate representation of a hex grid.
 *
 * Since only cells within distance n can matter, BFS up to depth n is sufficient.
 */

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static long encode(int x, int y) {
        return (((long) x) << 32) ^ (y & 0xffffffffL);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();
        int m = fs.nextInt();

        HashSet<Long> blocked = new HashSet<>(m * 2 + 1);
        for (int i = 0; i < m; i++) {
            int x = fs.nextInt();
            int y = fs.nextInt();
            blocked.add(encode(x, y));
        }

        long start = encode(0, 0);
        if (blocked.contains(start)) {
            System.out.println(0);
            return;
        }

        int[] dx = {1, -1, 0, 0, 1, -1};
        int[] dy = {0, 0, 1, -1, -1, 1};

        ArrayDeque<int[]> q = new ArrayDeque<>();
        HashSet<Long> visited = new HashSet<>();

        q.add(new int[]{0, 0, 0});
        visited.add(start);

        long ans = 0;

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int x = cur[0], y = cur[1], d = cur[2];
            ans++;

            if (d == n) continue;

            for (int k = 0; k < 6; k++) {
                int nx = x + dx[k];
                int ny = y + dy[k];
                long code = encode(nx, ny);
                if (blocked.contains(code) || visited.contains(code)) continue;
                visited.add(code);
                q.add(new int[]{nx, ny, d + 1});
            }
        }

        System.out.println(ans);
    }
}
